-- Immutable release load. Current schema must be operator-owned.
SET DEFINE OFF
ALTER SESSION SET NLS_NUMERIC_CHARACTERS = '.,';
ALTER SESSION SET TIME_ZONE = '+00:00';
COMMIT;
DROP SEQUENCE mission_id_seq;
DROP SEQUENCE change_id_seq;
CREATE SEQUENCE mission_id_seq START WITH 997092 MINVALUE 1 MAXVALUE 101559956668415 INCREMENT BY 1 NOCACHE NOCYCLE;
CREATE SEQUENCE change_id_seq START WITH 9906248 MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 NOCACHE NOCYCLE;
